import { Link } from "react-router-dom";
import { ErrorNote, fmt, PageHeader, Panel } from "../../components/ui";
import { usePoll } from "../../hooks/useChannel";
import { api } from "../../services/api";

const pct = (v: number | null | undefined) => (v === null || v === undefined ? "—" : `${Math.round(v * 100)}%`);
const CTRL: Record<string, string> = { pid: "PID", mpc: "MPC", ppo: "PPO (guard: flag only)", ppo_guarded: "PPO + guard → PID" };

/** Hurdle "The Sensor That Lies": the measured evidence, generated by full simulation runs. */
export default function Evidence() {
  const ev = usePoll(() => api.get("/api/touchdown/evidence"), 0);
  const d = ev.data;
  const sd = d?.sensor_drift, ds = d?.domain_shift;
  const fig = (n: string, cap: string) => d?.figures?.includes(n) && (
    <figure className="rounded-[14px] border overflow-hidden bg-white"><img src={api.url(`/api/touchdown/evidence/figure/${n}`)} alt={cap} className="w-full" />
      <figcaption className="px-3 py-2 text-[11.5px] text-ink2">{cap}</figcaption></figure>);
  const worlds = ds ? Object.keys(ds.worlds) : [];
  return (
    <div>
      <PageHeader eyebrow="Hurdle · The Sensor That Lies" title={<>Hurdle <em>Evidence</em></>}>
        <Link to="/app/landing?env=mars" className="btn btn-primary">Run it live</Link>
      </PageHeader>
      <ErrorNote error={ev.error} />
      <div className="grid md:grid-cols-3 gap-4 mb-5">
        {[["1 · A sensor that keeps talking", "Slow bias drift on the altimeter, TRN position or velocimeter. Readings stay valid and noisy — each one passes the EKF gate."],
          ["2 · A learned controller in a new world", "PPO trained in one envelope, flown with matched seeds against PID and MPC in four worlds it never saw."],
          ["3 · The exact moment", "CUSUM crossing its threshold, the confirmation test, the decision-log entry and the guard flag — all timestamped."]].map(([h, t]) => (
          <div key={h} className="panel p-4"><div className="text-[13.5px] font-semibold text-ink">{h}</div><div className="text-[12px] text-ink2 mt-1">{t}</div></div>))}
      </div>
      <Panel eyebrow="Synthetic dataset · full simulation runs" title="Lying-sensor detection">
        {!sd ? <div className="text-[12px] text-muted">Not generated yet: <code>python -m experiments.runners.sensor_drift_dataset --seeds 6 --workers 8</code></div> : <>
          <div className="text-[12.5px] text-ink2 mb-3">{sd.runs} missions · drift starts at t = {sd.onset_s} s · {sd.seeds_per_case} seeds per case ·
            <b className="text-ink"> false alarms: {pct(sd.false_alarm_rate)}</b> of {sd.clean_runs} fault-free missions (all landed: {pct(sd.clean_success_rate)})</div>
          <div className="overflow-x-auto"><table className="w-full text-[12.5px]">
            <thead><tr className="text-left text-muted text-[11px]">{["Lying sensor", "Drift rate", "Detected", "Correct sensor blamed", "Mean delay", "Max delay", "Safe landings: monitor ON", "monitor OFF"].map((h) => <th key={h} className="py-1.5 pr-3 font-medium">{h}</th>)}</tr></thead>
            <tbody>{sd.cases.map((c: any) => <tr key={c.channel + c.rate} className="border-t">
              <td className="py-1.5 pr-3 font-medium">{c.channel}</td><td className="pr-3 num">{c.rate}/s</td><td className="pr-3">{pct(c.detection_rate)}</td>
              <td className="pr-3">{pct(c.correct_blame_rate)}</td><td className="pr-3 num">{fmt(c.delay_mean_s, 1)} s</td><td className="pr-3 num">{fmt(c.delay_max_s, 1)} s</td>
              <td className="pr-3 text-success font-medium">{pct(c.success_monitor_on)}</td><td className={c.success_monitor_off < c.success_monitor_on ? "text-danger font-medium" : ""}>{pct(c.success_monitor_off)}</td></tr>)}</tbody>
          </table></div>
          <div className="grid lg:grid-cols-2 gap-4 mt-4">
            {fig("fig_2_innovation_lean.png", "Honest noise scatters on both sides of zero; a drifting sensor keeps leaning one way.")}
            {fig("fig_3_cusum_detection.png", "The exact moment: drift begins → SUSPECT → ISOLATED.")}
            {fig("fig_1_readings_vs_truth.png", "The altimeter keeps reporting — every reading plausible — while the hidden bias grows.")}
            {fig("fig_5_outcomes_on_vs_off.png", "What the lie costs when nobody catches it (same seeds, monitor ON vs OFF).")}
          </div></>}
      </Panel>
      <div className="h-5" />
      <Panel eyebrow="Matched-seed study" title="Learned vs classical controllers in worlds the learned one never saw">
        {!ds ? <div className="text-[12px] text-muted">Not generated yet: <code>python -m experiments.runners.domain_shift --seeds 6 --workers 8</code></div> : <>
          <div className="text-[12.5px] text-ink2 mb-3">{ds.seeds} seeds per cell · model <code className="text-[11px]">{String(ds.model).split(/[\\/]/).slice(-2).join("/")}</code> · success with 95% Wilson interval</div>
          <div className="overflow-x-auto"><table className="w-full text-[12.5px]">
            <thead><tr className="text-left text-muted text-[11px]"><th className="py-1.5 pr-3 font-medium">World</th>{ds.controllers.map((c: string) => <th key={c} className="pr-3 font-medium">{CTRL[c]}</th>)}</tr></thead>
            <tbody>{worlds.map((w) => <tr key={w} className="border-t align-top">
              <td className="py-2 pr-3 font-medium">{ds.worlds[w]}</td>
              {ds.controllers.map((c: string) => { const t = ds.table.find((x: any) => x.world === w && x.controller === c);
                return <td key={c} className="py-2 pr-3"><div className={t.success_rate >= 0.8 ? "text-success font-medium" : t.success_rate >= 0.5 ? "text-warning font-medium" : "text-danger font-medium"}>
                  {t.successes}/{t.n} <span className="text-muted text-[10.5px]">[{pct(t.ci_low)}–{pct(t.ci_high)}]</span></div>
                  <div className="text-[10.5px] text-muted num">err {fmt(t.landing_error_m, 1)} m · vz {fmt(t.touchdown_speed, 2)}</div>
                  {t.guard_flag_rate !== null && <div className="text-[10.5px]" style={{ color: t.guard_flag_rate > 0 ? "#b45309" : "#6b7280" }}>guard flagged {pct(t.guard_flag_rate)}{t.guard_t_mean != null && ` · t≈${fmt(t.guard_t_mean, 0)} s`}</div>}
                  {t.failures?.length > 0 && <div className="text-[10.5px] text-danger">{t.failures.join(", ")}</div>}</td>; })}</tr>)}</tbody>
          </table></div>
          <div className="mt-4">{fig("fig_domain_shift.png", "Safe-landing rate per world and controller (matched seeds).")}</div></>}
      </Panel>
    </div>
  );
}
